using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class VisualMaterialAuthoring {
 const string root="Assets/Art/VisualPass/";
 public static void Apply(){
  foreach(var path in AssetDatabase.FindAssets("t:Texture2D",new[]{root}).Select(AssetDatabase.GUIDToAssetPath)){
   var i=AssetImporter.GetAtPath(path) as TextureImporter;if(i==null)continue;bool normal=path.Contains("_normal"),mask=path.Contains("_mask");i.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;i.sRGBTexture=!normal&&!mask;i.mipmapEnabled=true;i.filterMode=FilterMode.Trilinear;i.anisoLevel=4;i.wrapMode=TextureWrapMode.Repeat;i.maxTextureSize=path.Contains("plastered")?2048:1024;
   i.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name="Android",overridden=true,maxTextureSize=i.maxTextureSize,format=normal?TextureImporterFormat.ASTC_5x5:TextureImporterFormat.ASTC_6x6});i.SaveAndReimport();
  }
  var map=new[]{("Stone","plastered_stone_wall",new Color(1,1,.93f),0f,.38f),("Wood","weathered_planks",new Color(.8f,.75f,.65f),0f,.3f),("Iron","green_metal_rust",new Color(.48f,.55f,.48f),.65f,.42f),("Brass","green_metal_rust",new Color(.75f,.48f,.15f),.8f,.65f),("WetStone","rock_boulder_dry",new Color(.34f,.41f,.45f),0f,.78f)};
  Directory.CreateDirectory(root+"Resources/VisualMaterials");AssetDatabase.Refresh();
  foreach(var entry in map){string path=root+"Resources/VisualMaterials/"+entry.Item1+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}Configure(m,entry.Item2,entry.Item3,entry.Item4,entry.Item5);}
  // Keep serialized material GUIDs so builders, shared references and central blackout modulation survive.
  foreach(var path in AssetDatabase.FindAssets("t:Material",new[]{"Assets/Art/Materials/Environment","Assets/WatchDemo"}).Select(AssetDatabase.GUIDToAssetPath)){
   string n=Path.GetFileNameWithoutExtension(path);string key=n.Contains("Plaster")||n=="M_Environment_Stone"?"Stone":n.Contains("Timber")||n=="Wood"?"Wood":n.Contains("Rock")?"WetStone":n.Contains("Brass")?"Brass":n=="M_Environment_Metal"||n=="Metal"||n=="Steel"||n=="LeakJoint"?"Iron":null;
   if(key==null)continue;var m=AssetDatabase.LoadAssetAtPath<Material>(path);var template=AssetDatabase.LoadAssetAtPath<Material>(root+"Resources/VisualMaterials/"+key+".mat");m.CopyPropertiesFromMaterial(template);m.shader=template.shader;EditorUtility.SetDirty(m);
  }
  ProjectShellUVs();AssetDatabase.SaveAssets();File.WriteAllText("artifacts/s4-master/part-c/material-import.txt","PASS: CC0 albedo/normal/packed metallic-AO-smoothness; ASTC6x6 colour/mask, ASTC5x5 normals; mipmaps + anisotropy4. Existing material GUIDs retained.");
 }
 static void ProjectShellUVs(){EditorSceneManager.OpenScene("Assets/Scenes/Lab/LK_Lab_Environment.unity");Directory.CreateDirectory(root+"UV");AssetDatabase.Refresh();foreach(var r in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include,FindObjectsSortMode.None)){
  string name=r.name;if(!name.StartsWith("SM_")||!(name.Contains("Wall")||name.Contains("Floor")||name.Contains("Stair")||name.Contains("Rail")||name.Contains("Trim")||name.Contains("Door")))continue;var f=r.GetComponent<MeshFilter>();if(!f||!f.sharedMesh)continue;var source=f.sharedMesh;if(AssetDatabase.GetAssetPath(source).StartsWith(root+"UV/",StringComparison.Ordinal))continue;string key=Hash128.Compute(AssetDatabase.GetAssetPath(source)+source.name+r.localToWorldMatrix.ToString("F4")).ToString();string path=root+"UV/"+key+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!m){m=UnityEngine.Object.Instantiate(source);m.name=source.name+" / metre UV";var vertices=m.vertices;var normals=m.normals;var uv=new Vector2[vertices.Length];for(int i=0;i<uv.Length;i++){var p=r.transform.TransformPoint(vertices[i]);var n=i<normals.Length?r.transform.TransformDirection(normals[i]):Vector3.up;n=new Vector3(Mathf.Abs(n.x),Mathf.Abs(n.y),Mathf.Abs(n.z));uv[i]=(n.y>=n.x&&n.y>=n.z?new Vector2(p.x,p.z):n.x>n.z?new Vector2(p.z,p.y):new Vector2(p.x,p.y))*.5f;}m.uv=uv;AssetDatabase.CreateAsset(m,path);}f.sharedMesh=m;
  }EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}
 static void Configure(Material m,string stem,Color c,float metal,float smooth){m.enableInstancing=true;m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(root+stem+"_albedo.jpg"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(root+stem+"_normal.jpg"));m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(root+stem+"_mask.png"));m.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(root+stem+"_mask.png"));if(m.name=="Brass"){m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(root+"brass_worn_albedo.jpg"));m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(root+"brass_worn_mask.png"));}m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");m.EnableKeyword("_OCCLUSIONMAP");m.SetColor("_BaseColor",c);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);m.SetFloat("_OcclusionStrength",.7f);m.SetFloat("_BumpScale",stem.Contains("stone_wall")?.30f:.45f);m.SetFloat("_Surface",0);m.SetFloat("_ZWrite",1);m.SetFloat("_Cull",0);m.SetOverrideTag("RenderType","Opaque");m.renderQueue=2000;EditorUtility.SetDirty(m);}
}
